import type { Publication } from './publication-manifest';

export const nov11ResearchPublications: readonly Publication[] = [{"publicationStatus":"reviewed","kind":"research","slug":"how-often-do-client-approvals-arrive-without-a-usable-receipt","title":"How often do client approvals arrive without a usable receipt?","description":"A method for counting approvals that cannot be verified, and for separating a missing record from a decision the client never made.","published":"2026-11-11","readingMinutes":8,"heroImage":"/hero/november-11/how-often-do-client-approvals-arrive-without-a-usable-receipt-hero.webp","thumbnail":"/thumbnails/november-11/how-often-do-client-approvals-arrive-without-a-usable-receipt.webp","heroAlt":"How often do client approvals arrive without a usable receipt?","topic":"approval receipts","relatedService":{"href":"/services","label":"Explore staffing services"},"relatedResource":{"href":"/blog/write-a-client-approval-receipt-the-team-can-verify","label":"Read the approval receipt guide"},"sources":[{"label":"National Archives, Records Management","href":"https://www.archives.gov/records-mgmt"},{"label":"NIST SP 800-53 Rev. 5, Security and Privacy Controls","href":"https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final"},{"label":"Plain Language Guidelines, plainlanguage.gov","href":"https://www.plainlanguage.gov/guidelines/"}],"sections":[{"id":"question-and-scope","heading":"Question and scope","paragraphs":["This review asks how often a client approval arrives without a receipt the team can verify. The unit is one approval that authorizes an action, such as a refund, a price change, or an access grant. The scope covers recurring assistant workflows where a client decision unlocks the next step. The review does not estimate a universal rate, because the decision type and the record system vary by client.","The question matters because an approval is only useful if the person acting on it can show what was decided. A message that says to go ahead may be enough for a small task, while a payment change needs a clear record of the amount and the approver. Without that record, the team may act on a guess or ask the client again. Both outcomes cost time and trust.","The review separates a missing receipt from a missing approval. The client may have approved the work in a call, but no one wrote it down. The client may also have expressed a preference that was never a decision. The first is a record problem, while the second is a scope problem. The fixes are different.","A useful review also records the cost of the gap. The cost may be a delayed start, a repeat message, or a correction after the work reached the client. Add the time spent waiting and the number of people involved. That evidence helps a manager decide whether to fix the template or the client conversation first."]},{"id":"define-usable-receipt","heading":"Define a usable receipt","paragraphs":["A usable receipt names the decision, the approver, the scope, the conditions, and the evidence. The decision should be specific enough to act on without interpretation. The approver should have the authority for that decision. The scope should name the accounts, amounts, or documents covered.","The evidence is the source the team can open later. It may be the client message, a signed form, or a system approval. A summary written by the assistant is not evidence unless it links to the original. The receipt should point to the source rather than replace it.","A receipt is usable when a second person can check it in under a minute. That person should be able to see who approved, what was approved, and where the proof lives. If the check requires reading a long thread or asking the original assistant, the receipt is incomplete. The test is reproduction, not politeness."]},{"id":"build-the-sample","heading":"Build the sample","paragraphs":["Start with the actions that required client approval during the past month. Include refunds, discounts, scope changes, access grants, public statements, and contract edits. Pull the task record and the client message for each one. A sample of twenty actions is enough to see a pattern in a small team.","For each action, record whether a receipt existed before the work began. Then record whether the receipt met the definition above. Do not count a receipt created after the fact as a pre-approval. A late record may still be useful, but it did not control the action.","Include the actions that were paused because the approval was unclear. Those cases show the cost of a weak receipt even when the work did not proceed. A team that only samples completed actions will miss the delay and the repeat questions. The paused cases are part of the evidence.","Record the risk level of each action so a missing receipt for a small request does not carry the same weight as a missing receipt for a payment change. A simple high, medium, and low scale is enough. The scale should reflect what could go wrong if the team acted on the wrong assumption. Report the high-risk cases separately in the final count."]},{"id":"measure-the-gap","heading":"Measure the gap","paragraphs":["Report the share of actions with no receipt, the share with a partial receipt, and the share with a usable receipt. Add the median time between the client message and the start of work. A team may have receipts for most actions but still wait days for a usable one. The time is part of the control.","Group the results by decision type and by client. A refund may have a stronger record than a scope change because the payment system requires one. A client with a single contact may have clearer approvals than a client with several stakeholders. The grouping shows where the process needs a standard.","Compare the rate with the number of approvals requested. A team that asks for approval constantly may have a high receipt rate because the process is explicit. A team that acts on informal messages may have a low rate and more rework. The count should be read with the volume and the risk."]},{"id":"why-receipts-fail","heading":"Why receipts fail","paragraphs":["A receipt fails when the approval arrives in a channel that is not connected to the task. A quick reply in a chat, a comment in a meeting, or a nod in a call may never reach the record. The team then relies on memory or asks again. The channel is the first design choice.","A receipt also fails when the template asks for more than the approval contains. A form with ten fields may be abandoned when the client sends a one-line message. The record should capture the minimum needed to act and to verify. Extra detail can be added later if the decision is complex.","A third cause is unclear authority. The assistant may not know whether the contact can approve the amount or only recommend it. The receipt then records a name without a role, and a later reviewer cannot tell whether the decision was valid. The authority rule belongs in the client brief, not in the assistant's memory.","A fourth cause is a template that is stored far from the task. The assistant may have to open a separate system, find the client, and copy the decision into two places. That effort is easy to skip on a busy day. The fix is to put the approval fields on the task itself and link the evidence from there."]},{"id":"controls-that-help","heading":"Controls that help","paragraphs":["Add an approval field to the task at the point where the work is created. The field should ask for the decision, the approver, the scope, and the evidence link. Make the field required before the task can move to the action stage. A required field is more reliable than a reminder.","Give the client a simple way to confirm a decision in writing. A short reply with the option and the amount is easier than a formal form. The assistant can prepare the summary and ask the client to confirm it. The confirmation becomes the evidence, and the summary reduces ambiguity.","Review a sample of receipts each month and fix the template when the same field is missing. A pattern of missing scope suggests the field is unclear, not that the team is careless. The review should improve the form, the training, and the client conversation. It should not become a search for someone to blame.","Track whether the client actually uses the confirmation format. A format that the client ignores will not produce a usable receipt. If the client prefers a short reply, adapt the template to accept that reply and capture it. The control should fit the relationship, not force the client into an internal form."]},{"id":"method-and-limitations","heading":"Method and limitations","paragraphs":["This review describes a local measurement method rather than a study of approval records across providers. The sources define records and access controls, but they do not supply a benchmark. The actual rate depends on the client, the decision type, and the tools available. A team should measure its own actions before setting a target.","The sample may miss approvals that were never recorded at all. A verbal approval may leave no trace, and a chat message may be deleted. The result is a minimum count of the problem, not a complete census. The team should note which channels were included and which were not."]},{"id":"decision-checklist","heading":"Decision checklist","paragraphs":["List the actions that require approval and the person who can give it. Define a usable receipt with the decision, approver, scope, conditions, and evidence. Sample the past month and count the missing and partial receipts. Group the results by decision type and client.","Add a required approval field to the task. Give the client a short confirmation format. Review a sample each month and change one part of the template. Measure the share of actions that start with a usable receipt."]}]},{"publicationStatus":"reviewed","kind":"research","slug":"what-share-of-queue-rework-traces-to-a-missing-cause-code","title":"What share of queue rework traces to a missing cause code?","description":"A method for coding returned work so the team can see which process failures create rework instead of only counting the returns.","published":"2026-11-11","readingMinutes":8,"heroImage":"/hero/november-11/what-share-of-queue-rework-traces-to-a-missing-cause-code-hero.webp","thumbnail":"/thumbnails/november-11/what-share-of-queue-rework-traces-to-a-missing-cause-code.webp","heroAlt":"What share of queue rework traces to a missing cause code?","topic":"rework causes","relatedService":{"href":"/services","label":"Explore staffing services"},"relatedResource":{"href":"/blog/build-a-rework-cause-code-list-from-queue-history","label":"Read the rework cause code guide"},"sources":[{"label":"NIST Baldrige Excellence Framework","href":"https://www.nist.gov/baldrige"},{"label":"Plain Language Guidelines, plainlanguage.gov","href":"https://www.plainlanguage.gov/guidelines/"},{"label":"U.S. Small Business Administration hire and manage employees","href":"https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"}],"sections":[{"id":"question-and-scope","heading":"Question and scope","paragraphs":["This review asks what share of queue rework can be traced to a missing or unclear cause code. The unit is a returned work item that had to be corrected, reopened, or clarified. The scope covers recurring assistant queues with a return or review step. The review does not estimate a universal rework rate, because the work type and the review standard vary by client.","The question matters because a return count alone does not tell the team what to fix. Ten returns from missing evidence need a different response than ten returns from unclear instructions. A cause code turns the count into a direction. Without it, the team may coach the same point or rewrite the wrong process.","The review separates a coded return from an uncoded one. A coded return has a reason that a second person can understand. An uncoded return may be recorded as quality issue or other. The uncoded group is not a failure of the worker; it is a gap in the record that hides the cause.","The review also asks whether the code is applied consistently enough to compare one month with the next. A code that means different things to different reviewers produces a false trend. The first step is to test agreement on a small sample before using the counts for a decision. The result should be read with the definitions and the sample, not as a standalone measure."]},{"id":"build-the-return-log","heading":"Build the return log","paragraphs":["Start with every item that came back during the period, including items returned by a client, a reviewer, or a downstream team. Add the date, the stage where it was found, and the stage where it was created. Include the original due date and the date the corrected work was delivered. If a stage is unknown, record it as unknown rather than guessing.","Read the note that came with each return. Copy the exact wording into the log before assigning a code. The wording is the evidence, and it prevents the coder from fitting the case to a preferred cause. If the note is missing, mark the case as uncoded rather than guessing.","Add the person who did the original work and the person who reviewed it. These fields are for the private quality record, not for a public ranking. The shared report should show causes and stages, not a league table of names. The purpose is process repair, not performance theater."]},{"id":"define-the-codes","heading":"Define the codes","paragraphs":["Use a short list that matches the work. A practical set includes unclear instruction, missing evidence, wrong source, tool or access failure, and judgment outside the role. Each code should describe a cause the team can change. A code that only describes a symptom will not point to a repair.","Write one example and one counterexample for each code. The examples should come from the team's actual returns. A return because the client name was taken from an old export is a wrong source case, while a return because the client changed the name is a new request. The pair settles the boundary.","Keep an unknown category and review it each week. A large unknown group means the codes are incomplete or the descriptions are unclear. Do not force a case into a code to make the report look complete. The unknown group is a prompt to improve the list.","Review the code list when a new service or client is added. A new deliverable may bring a failure mode the old codes cannot describe. Add a code only when a real group of cases needs it. Record the date and the reason so the history of the list stays visible."]},{"id":"measure-the-share","heading":"Measure the share","paragraphs":["Report the share of returns with a usable code and the share without one. A usable code has a definition, an example, and enough evidence for a second reviewer to agree. A bare label such as quality issue is not usable. The coded share shows whether the team can learn from its returns.","For the coded returns, report the distribution by cause and by creation stage. A cause that appears mostly at intake points to the brief or the form. A cause that appears at delivery points to the review or the final check. The stage is often more actionable than the label.","Compare the rework count with the volume of completed work. A rising count may reflect more volume rather than worse quality. Report the share of completed items that returned and the median time to correct them. The two numbers give a fairer view than a raw count."]},{"id":"what-the-pattern-shows","heading":"What the pattern shows","paragraphs":["A large unclear instruction group suggests the brief is not specific enough. The team may be asking the assistant to use judgment without naming the standard. The fix is a better task card, an example, or a short decision rule. Coaching the assistant without changing the brief will not move the pattern.","A large missing evidence group suggests the intake form or the client request is incomplete. The queue is accepting work that cannot be finished. The fix is a required field and a return path before the work starts. The assistant should not become the person who chases every missing document after the deadline.","A large tool or access group suggests the environment is slowing the work. The fix may be a permission, a saved view, or a different tool. A quality review that ignores the tool will blame the person for a system problem. The code helps separate the two.","A large judgment group may mean the role boundary is unclear. The assistant may be making a decision that belongs to the client or the manager. The fix is a written limit and an escalation path, not a longer training session. The code should point to the boundary, not to the person."]},{"id":"controls-that-help","heading":"Controls that help","paragraphs":["Put the code field on the return form and require it before the item can be closed. The person who handles the return usually knows the reason and can record it quickly. A monthly reconstruction will produce guesses and disagreement. The code should be part of the workflow, not a separate report.","Review a sample of coded returns with a second reviewer each week. Compare the code with the note and the evidence. Disagreement is normal at first and usually points to a vague definition. Revise the definition rather than arguing about individual cases.","Give each code an owner and one likely repair. The owner should be the person who can change the cause. Track the code for two weeks after the repair and see whether the share moves. A code without an owner becomes a label that everyone recognizes and no one fixes.","Keep the code definitions where the team works. A list in a manager notebook will be applied differently by each person. Put the definitions beside the return form and link them in the weekly note. The same words should appear in the training and the report."]},{"id":"method-and-limitations","heading":"Method and limitations","paragraphs":["This review describes a local coding method rather than a controlled study of rework causes. The sample depends on the returns the team records and the notes that survive. Some returns are resolved in conversation and never logged. The result is a floor rather than a complete count.","The coding itself can change behavior. People may write clearer return notes because they know the case will be coded. That effect can improve the record, but it makes the first period a weak baseline. Use a later period for comparison and note when the coding began.","A coding review should also record whether the return note changed after the code was assigned. A later edit can make the original code look wrong even when it was right at the time. Keep the original note and add the correction as a separate entry. The history is more useful than a clean record with no trace."]},{"id":"decision-checklist","heading":"Decision checklist","paragraphs":["Build a return log with the note, the finding stage, and the creation stage. Define five codes with examples and counterexamples. Code at the time of return and keep an unknown category. Review a sample with a second person.","Report the coded share, the cause distribution, and the creation stage. Give each code an owner and one repair. Measure the code again after the change. Keep the list stable enough to compare months."]}]},{"publicationStatus":"reviewed","kind":"research","slug":"does-a-sop-stress-test-expose-gaps-before-a-live-handoff","title":"Does a SOP stress test expose gaps before a live handoff?","description":"A way to test whether a written procedure works for someone who did not write it, using a safe case and an observed run.","published":"2026-11-11","readingMinutes":8,"heroImage":"/hero/november-11/does-a-sop-stress-test-expose-gaps-before-a-live-handoff-hero.webp","thumbnail":"/thumbnails/november-11/does-a-sop-stress-test-expose-gaps-before-a-live-handoff.webp","heroAlt":"Does a SOP stress test expose gaps before a live handoff?","topic":"SOP stress tests","relatedService":{"href":"/services","label":"Explore staffing services"},"relatedResource":{"href":"/blog/run-a-quarterly-sop-stress-test-with-a-new-assistant","label":"Read the SOP stress test guide"},"sources":[{"label":"NIST Baldrige Excellence Framework","href":"https://www.nist.gov/baldrige"},{"label":"Plain Language Guidelines, plainlanguage.gov","href":"https://www.plainlanguage.gov/guidelines/"},{"label":"U.S. Small Business Administration hire and manage employees","href":"https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"}],"sections":[{"id":"question-and-scope","heading":"Question and scope","paragraphs":["This review asks whether a SOP stress test exposes gaps before a live handoff. The unit is one procedure tested by a person who did not write it. The scope covers recurring assistant procedures with a review or client-facing step. The review does not estimate a universal failure rate, because the procedure and the tester experience vary.","The question matters because a document can look complete to its author and fail for everyone else. The author fills gaps from memory and skips steps that seem obvious. A new person cannot do that. A stress test makes the hidden knowledge visible before a client or a deadline finds it.","The review separates a document gap from a tester gap. A document gap is a missing step, link, or decision rule. A tester gap is a skill or experience the role would normally require. The same failure can come from either, so the test should record what the tester knew and what the document provided.","The review also records whether the tester had the access the role would normally provide. A missing permission can look like a document gap if no one checks. Separate the two before drawing a conclusion. The access check is part of the test design, not a separate exercise."]},{"id":"design-the-test","heading":"Design the test","paragraphs":["Choose a procedure with real risk and recent change. A refund, an onboarding step, or a client report is a better candidate than a simple filing task. Pick one where a missed step would reach a client or a payment. The test should spend its effort where the cost of failure is highest. The procedure should be one the team would actually use under deadline pressure.","Use a tester who does not do the task every day. A new assistant, a backup, or a colleague from another team is a better tester than the author. The author knows the shortcuts and will not reveal the gaps. The test measures the document, not the expert.","Build a safe case with invented records but real structure. Use the same fields, file names, and approval points as live work. Remove personal and financial data that the test does not need. The case should be realistic enough to test the path without creating a privacy risk.","Write the expected result before the tester starts. State what a correct output looks like and what evidence should be attached. The tester should not see the expected result until they finish. Comparing their output with the standard is the point of the exercise."]},{"id":"observe-the-tester","heading":"Observe the tester","paragraphs":["Let the tester work without step-by-step guidance. Note the questions, the pauses, and the tools they open. Answer only if a real colleague could answer from the same document. A question that the document cannot answer is a finding, not a failure of the tester.","Record the time from start to finish and the time spent searching. A procedure that takes twice as long as expected may still be accurate, but it may miss a deadline. The time is part of the result. Note where the delay occurred rather than only the total.","Ask the tester to mark each step as clear, unclear, or missing. Add a short note beside each mark. The self-report helps explain the observed behavior, but it is not the only evidence. Compare the marks with the actions the tester actually took."]},{"id":"compare-the-result","heading":"Compare the result","paragraphs":["Compare the tester's output with the expected result written before the test. Count the errors and note whether they came from the document or from the tester's experience. A correct guess may still reveal a gap. The document should work for the next person who does not guess.","Group the findings into access, instruction, tool, and decision gaps. Each type has a different owner and a different repair. A missing permission needs an access change, while a missing approval needs a decision rule. The grouping keeps the action list specific.","Rank the gaps by the risk they would create in live work. A missing approval is more serious than a confusing file name. A wrong template is more serious than a slow search. The ranking helps the team fix the highest-risk gap first rather than the easiest one."]},{"id":"interpret-the-gaps","heading":"Interpret the gaps","paragraphs":["A missing step is the clearest finding. The document should name the action, the tool, and the expected result. If the step exists but is buried, the problem is structure rather than content. The repair may be a link, a heading, or a shorter page.","A missing decision rule is a management gap. The tester may have stopped because they did not know who could approve an exception. The fix is a named owner and a limit, not a longer narrative. Write the rule where the decision occurs in the procedure.","A missing access step is an environment gap. The tester may have the right instruction but not the permission. The fix is a role change or a temporary grant with an expiry. Do not treat an access failure as a training issue. The person cannot practice a task they cannot open.","A gap that appears in several testers is a document problem. A gap that appears only with one tester may be a skill or experience issue. The pattern matters more than a single run. Run the same case with a second person before rewriting the whole procedure."]},{"id":"controls-that-help","heading":"Controls that help","paragraphs":["Run the test on a fixed cadence and rotate the procedures. Put the next test on the same calendar as the access review. A procedure tested only after an incident is a reaction. A regular test catches drift before a client does. Put the schedule where the team can see it and name the person who owns the next test.","Fix one high-risk gap and retest that step with a different tester. The second test shows whether the change is understandable to someone who did not help write it. If the same gap appears, the change was not specific enough. Revise the wording rather than adding another note.","Record the change and the tester in the SOP history. A future reviewer should see why the step looks the way it does. The history also shows whether the procedure is maintained or only tested once a year. Keep it in the same folder as the SOP.","Keep the test case in a shared folder with the expected result and the version of the SOP. A future tester should be able to repeat the exercise without rebuilding it. The case should be updated when the work changes. A stale test case can give a false sense of coverage."]},{"id":"method-and-limitations","heading":"Method and limitations","paragraphs":["This review describes a local test method rather than a controlled study of SOP quality. The sample is small and depends on the tester and the case. A tester with relevant experience may find fewer gaps than a true beginner. A tester with no context may fail for reasons the role would not face.","The test can also change the procedure before the next measure. The team may fix the document immediately, which is the point, but it makes the first result a weak baseline. Record the version tested and the date. Repeat the test after the change to see the effect.","The test case itself can become a source of error. If the case is unrealistic or too simple, the result may overstate the procedure. Review the case with the person who does the work before the test. A realistic case is part of the method, not an afterthought."]},{"id":"decision-checklist","heading":"Decision checklist","paragraphs":["Choose a risky procedure and a tester who did not write it. Build a safe case with real structure. Observe without rescuing and record the questions and time. Compare the output with the expected result.","Group the gaps into access, instruction, tool, and decision. Rank them by live risk. Fix one gap and retest with a different person. Record the change and schedule the next procedure."]}]},{"publicationStatus":"reviewed","kind":"research","slug":"how-current-is-a-client-preference-register-after-a-year","title":"How current is a client preference register after a year?","description":"A method for measuring preference drift, stale entries, and contradictions before an old note shapes the next client message.","published":"2026-11-11","readingMinutes":8,"heroImage":"/hero/november-11/how-current-is-a-client-preference-register-after-a-year-hero.webp","thumbnail":"/thumbnails/november-11/how-current-is-a-client-preference-register-after-a-year.webp","heroAlt":"How current is a client preference register after a year?","topic":"client preferences","relatedService":{"href":"/services","label":"Explore staffing services"},"relatedResource":{"href":"/blog/keep-a-client-preference-register-current","label":"Read the client preference register guide"},"sources":[{"label":"Plain Language Guidelines, plainlanguage.gov","href":"https://www.plainlanguage.gov/guidelines/"},{"label":"NIST Baldrige Excellence Framework","href":"https://www.nist.gov/baldrige"},{"label":"U.S. Small Business Administration hire and manage employees","href":"https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"}],"sections":[{"id":"question-and-scope","heading":"Question and scope","paragraphs":["This review asks how current a client preference register remains after a year of use. The unit is one preference entry that affects how assistant work is done. The scope covers tone, channel, timing, format, and meeting preferences recorded for a client. The review does not estimate a universal drift rate, because the client relationship and the review cadence vary.","The question matters because a preference can become a rule that no one remembers setting. The client may have changed contacts, tools, or expectations while the register stayed the same. A stale entry is worse than no entry because the team treats it as current. The cost is a small misstep that accumulates into a trust problem.","The review separates a preference from a policy. A preference can change with a conversation, while a policy needs a formal update. The register should show which is which. A stale preference may be harmless, while a stale policy may create a compliance or access risk.","The review also looks at whether the register is used at all. A current register that no one opens does not improve the work. Check whether the preference appears in the task brief and the handover. Use is part of currency because an unused record cannot be corrected by the team."]},{"id":"build-the-sample","heading":"Build the sample","paragraphs":["Take the full register for one or two clients and list every entry. Include the source, the date, and the person who confirmed it. If the register does not have those fields, that absence is the first finding. A register without dates cannot be assessed for currency. A small sample is enough to show whether the register is maintained.","Choose a sample of entries that affect client-facing work. Tone, channel, response time, and meeting format are good candidates because they are easy to observe. Add a few entries that affect internal work, such as file naming or approval style. The mix shows whether the drift is limited to one area. Record the risk of each entry so the biggest gaps are fixed first.","Compare each entry with the most recent client messages, meeting notes, and instructions. Look for a direct contradiction, a silent change, or a missing confirmation. A contradiction is the strongest signal, while a missing confirmation is a weaker one. Record the evidence for each judgment.","Record the risk of each preference. A tone preference may be low risk, while a channel or approval preference may affect a commitment. A contradiction in a high-risk entry deserves a faster review. The risk level helps the team decide which entries to confirm first."]},{"id":"define-current","heading":"Define current","paragraphs":["An entry is current when the client has confirmed it within the review period and no later message contradicts it. The review period should match the relationship. A quarterly client may need a quarterly check, while a stable annual client may need a yearly one. Write the period at the top of the register.","An entry is also current when the source is still valid. A preference set by a contact who has left the client may no longer represent the account. The register should show the source and the date, not only the preference. A valid source is part of the definition.","Treat a preference as stale when a newer client message points the other way. Do not wait for a formal confirmation to notice the conflict. Mark the entry as under review and ask the client. The question is short and shows that the team is paying attention."]},{"id":"measure-drift","heading":"Measure the drift","paragraphs":["Report the share of entries confirmed within the period, the share older than the period, and the share with no source. Add the share with a direct contradiction. The four numbers tell a more useful story than a single currency rate. A register can be old but accurate, or new but contradictory.","Group the results by preference type and by client contact. A channel preference may drift faster than a meeting format because tools change. A client with several contacts may have more contradictions than one with a single owner. The grouping shows where to focus the review.","Compare the register with the quality sample. If reviewers find the same preference error repeatedly, the register may be hard to find or unclear. If the register is current but the work still misses, the problem may be training or access. The comparison separates a record problem from a behavior problem."]},{"id":"why-entries-go-stale","heading":"Why entries go stale","paragraphs":["An entry goes stale when the client changes a contact and no one updates the register. The new contact may have different expectations, but the old note still guides the work. The handover from the old contact is the moment to review the preferences. Without that step, the register quietly becomes history.","An entry also goes stale when the service changes. A new report, a new tool, or a new meeting cadence can make an old format preference irrelevant. The register should be reviewed when the scope changes, not only on a calendar. The service change is a stronger trigger than the date.","A third cause is a preference that was never confirmed. Someone heard a comment and recorded it as a rule. The entry has a date but no source. Over time it becomes indistinguishable from a confirmed preference. The fix is to require a source and to review unsourced entries first.","A fourth cause is a register that is too long to review. When every detail is recorded, the important preferences are buried. The team stops reading the whole list and relies on memory. A shorter register with clear priorities is easier to keep current and more likely to be used."]},{"id":"controls-that-help","heading":"Controls that help","paragraphs":["Require a source and a confirmation date for every entry. Make the source a link or a message reference, not a name alone. Review the unsourced entries first and either confirm or remove them. A short register with good sources is more useful than a long one with guesses.","Put the register review on the client check-in agenda. Ask the client to confirm three or four preferences that affect the next quarter. A short list is easier to answer than an open request to review everything. The confirmation becomes the new date.","Remove or archive entries that no longer apply. Mark the retirement date and the reason. A register that only grows becomes a confusing mix of old and new instructions. The history explains why a rule disappeared, while the current list stays usable.","Give the client a short summary of the current preferences at the check-in. The summary is easier to correct than an open question about everything. Ask for a yes or no on each item and record the date. The conversation takes a few minutes and prevents months of small missteps."]},{"id":"method-and-limitations","heading":"Method and limitations","paragraphs":["This review describes a local currency check rather than a study of preference drift across clients. The sample depends on the records the team keeps and the access to the client. Some preferences are confirmed in conversation and never written down. The result is a floor rather than a complete count.","The client may also change behavior because the review is happening. They may confirm preferences more carefully or update the team without being asked. That effect is useful, but it makes the first period a weak baseline. Use a later period and note when the review began.","A preference review should also note which entries were never used. An unused entry may still be correct, but it adds length and confusion. Ask whether the work would miss it if the entry disappeared. The answer helps decide whether to keep, merge, or retire the note."]},{"id":"decision-checklist","heading":"Decision checklist","paragraphs":["List every preference with its source, date, and confirmer. Sample the entries that affect client-facing work. Compare each with recent messages and instructions. Define current with a review period and a valid source.","Report confirmed, old, unsourced, and contradictory entries. Group by type and contact. Require a source for new entries. Review the register at the client check-in and after every service change."]}]},{"publicationStatus":"reviewed","kind":"research","slug":"where-does-a-shift-handover-lose-task-ownership","title":"Where does a shift handover lose task ownership?","description":"A way to trace open work across a shift change and find the exact point where the next action, the owner, or the acceptance disappears.","published":"2026-11-11","readingMinutes":8,"heroImage":"/hero/november-11/where-does-a-shift-handover-lose-task-ownership-hero.webp","thumbnail":"/thumbnails/november-11/where-does-a-shift-handover-lose-task-ownership.webp","heroAlt":"Where does a shift handover lose task ownership?","topic":"shift handover","relatedService":{"href":"/services","label":"Explore staffing services"},"relatedResource":{"href":"/blog/design-a-shift-handover-checklist-for-assistant-teams","label":"Read the shift handover checklist guide"},"sources":[{"label":"U.S. Small Business Administration hire and manage employees","href":"https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"},{"label":"NIST SP 800-53 Rev. 5, Security and Privacy Controls","href":"https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final"},{"label":"Plain Language Guidelines, plainlanguage.gov","href":"https://www.plainlanguage.gov/guidelines/"}],"sections":[{"id":"question-and-scope","heading":"Question and scope","paragraphs":["This review asks where a shift handover loses task ownership. The unit is an open task that crosses from one shift to the next. The scope covers assistant teams with overlapping or consecutive shifts and a shared queue. The review does not estimate a universal handover failure rate, because the schedule and the work mix vary.","The question matters because a handover is the moment when a task can become everyone's responsibility and no one's job. The sender believes the receiver has it, while the receiver believes the task is still with the sender. The gap may not appear until a client asks for an update. By then, the deadline may be gone.","The review separates a lost task from a late task. A lost task has no current owner or next action. A late task may still have an owner but miss the deadline. The first is a handover failure, while the second may be a capacity or priority issue. The fixes are different.","The review also separates a task that was never accepted from a task that was accepted and then dropped. The first is a handover gap, while the second may be a capacity or priority problem. Recording both stages shows where the ownership actually disappeared. That difference determines whether the fix is a schedule change or a capacity change."]},{"id":"trace-the-handover","heading":"Trace the handover","paragraphs":["Pick a set of tasks that crossed a shift boundary during the past two weeks. Include tasks that moved smoothly and tasks that stalled. Trace each one through the queue, the handover note, and the first action on the next shift. Record the times and the people involved.","Identify the sender, the receiver, and the moment the receiver accepted the task. If there is no acceptance step, record that as a finding. If the receiver accepted but did not act, record the reason. The reason may be capacity, access, or an unclear next step.","Compare the handover note with the task record. A note that says the task is in progress is weaker than one that names the next action and the owner. A task record that contradicts the note shows which source the team actually uses. The comparison reveals the real handover process.","Record the time the sender wrote the note and the time the receiver first opened the task. A long gap between the two may show that the handover happened too early or that the receiver was busy. The timing is evidence of the handover window, not proof of intent. A long gap is a prompt to check the acceptance step, not a reason to blame the receiver."]},{"id":"define-ownership","heading":"Define ownership","paragraphs":["A task has an owner when one named person is accountable for the next action. The owner may need help from others, but the accountability should not be shared. A group name or a queue name is not an owner. The owner should know they have the task and when it is due.","Ownership also needs a next action and a date. A task that is waiting has a date when someone will check it. A task that is moving has a specific action and a person who will do it. Without one of those, the task is in a holding pattern rather than owned.","The owner should be visible in the same place the work lives. A name in a separate handover note may not reach the task board. The receiver should not have to reconcile two records. Put the owner and the next date in the task, and use the note to summarize."]},{"id":"find-the-drop-points","heading":"Find the drop points","paragraphs":["A common drop point is the end of a shift when the sender leaves before the receiver accepts. The task sits in a channel that no one is watching. The fix is a required acceptance step and a named backup when the receiver is unavailable. The acceptance should be quick and visible.","Another drop point is a task with multiple contributors. Each person assumes someone else is leading, and no one writes the next action. The fix is one owner and a short list of contributions. The owner does not have to do all the work, but they must track it.","A third drop point is a sensitive task that moves to a restricted path. The general handover note shows a reference, but the receiver never opens the restricted record. The fix is a confirmation that the receiver has the access and has read the task. A reference without acceptance is not a handover.","A fourth drop point is a task that depends on a decision from someone outside the shift. The team may hand over the task but not the decision request. The receiver then waits without knowing who should follow up. Add the external owner and the date to the handover note."]},{"id":"interpret-the-pattern","heading":"Interpret the pattern","paragraphs":["If most drops happen at the same time of day, the handover window may be too short or too busy. The team may be trying to transfer work while also finishing the current shift. A fixed handover window with no other meetings can reduce the gap. The schedule is part of the design.","If most drops involve the same task type, the brief for that type may be unclear. A task that requires a decision may lack a named decision owner. A task that requires access may lack a permission. The type points to the repair more than the individual case.","If most drops involve the same receiver, the issue may be capacity rather than the handover. A person who accepts every task but has no time to act is not covered. The fix may be a smaller queue, a different shift, or a backup. The review should not blame the receiver for a capacity problem."]},{"id":"controls-that-help","heading":"Controls that help","paragraphs":["Require an acceptance step at the shift boundary. The receiver confirms the list and names any task they cannot take. The sender does not leave until the list is accepted or escalated. A simple confirmation prevents the silent gap between two people who both think the other has the task.","Keep one queue view with the owner, the next action, and the age. The handover note should summarize the view rather than replace it. A receiver who can see the queue does not have to reconstruct the work from a message. The view should be available before the shift starts.","Review a small sample of handovers each week and look for repeated questions. A question that appears every week points to a missing field or an unclear rule. Fix the field rather than relying on the sender to explain it again. The handover should improve with each cycle.","Test the handover with a real task during a quiet period. Ask the receiver to restate the top priorities and the next action for one item. The test takes minutes and reveals whether the note is usable. Repeat it after a schedule change or a new client."]},{"id":"method-and-limitations","heading":"Method and limitations","paragraphs":["This review describes a local tracing method rather than a controlled study of handover failure. The sample depends on the tasks the team records and the notes that survive. Some handovers happen verbally and leave no trace. The result is a floor rather than a complete count.","The team may also change behavior while the review is running. People may accept tasks more carefully or write clearer notes because they know the handover is being watched. That effect is useful, but it makes the first period a weak baseline. Use a later period and note when the review began.","The schedule itself can create a false result. A quiet week may make the handover look healthier than it is, while a holiday week may make it look worse. Compare several weeks and note the workload. The pattern across different conditions is stronger evidence than a single sample."]},{"id":"decision-checklist","heading":"Decision checklist","paragraphs":["Sample tasks that crossed a shift and trace the sender, receiver, acceptance, and first action. Define ownership as one named person with a next action and a date. Find the drop points by time, task type, and receiver. Record the date and the people for each item so the pattern can be checked later.","Require an acceptance step at the boundary. Keep one queue view with owner, action, and age. Review a sample of handovers each week. Fix one field or one schedule issue and measure the next cycle."]}]},{"publicationStatus":"reviewed","kind":"research","slug":"how-long-do-call-recordings-outlive-their-retention-rule","title":"How long do call recordings outlive their retention rule?","description":"A method for comparing the written retention period with the recordings and copies still stored, including transcripts and exports.","published":"2026-11-11","readingMinutes":8,"heroImage":"/hero/november-11/how-long-do-call-recordings-outlive-their-retention-rule-hero.webp","thumbnail":"/thumbnails/november-11/how-long-do-call-recordings-outlive-their-retention-rule.webp","heroAlt":"How long do call recordings outlive their retention rule?","topic":"call recording retention","relatedService":{"href":"/services","label":"Explore staffing services"},"relatedResource":{"href":"/blog/set-a-data-retention-schedule-for-call-recordings","label":"Read the call recording retention guide"},"sources":[{"label":"FTC Business Guidance, Privacy and Security","href":"https://www.ftc.gov/business-guidance/privacy-security"},{"label":"NIST SP 800-53 Rev. 5, Security and Privacy Controls","href":"https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final"},{"label":"National Archives, Records Management","href":"https://www.archives.gov/records-mgmt"}],"sections":[{"id":"question-and-scope","heading":"Question and scope","paragraphs":["This review asks how long call recordings remain stored after their retention period ends. The unit is one recording or a derived copy such as a transcript or an export. The scope covers calls recorded by an assistant team for quality, training, or client service. The review does not estimate a universal overrun, because the legal and client requirements vary.","The question matters because a recording can hold sensitive personal or commercial information. Keeping it longer than necessary increases the harm if it is exposed. It also increases storage cost and the work of answering a client question. A retention rule that is not enforced is only a statement of intent.","The review separates the recording from its copies. A phone system may delete the audio on schedule while a downloaded file or a transcript remains in a shared folder. The copy is often easier to share and harder to track. The review should count both.","The review also asks whether the retention rule is visible to the people who record and share calls. A rule in a policy document that the team never reads is not a control. Put the period and the deletion path in the call script and the shared workspace. A notice that the team never sees cannot guide the recording decision."]},{"id":"build-the-inventory","heading":"Build the inventory","paragraphs":["Start with each system that can store a recording. Include the phone platform, the meeting tool, the support desk, and any shared drive used for exports. Add the owner of each system and the person who can delete a file. An inventory built only from the main tool will miss the copies.","List the recordings by date, purpose, client, and storage location. Add the retention period that applies and the expected deletion date. If the purpose is unclear, mark it as unknown rather than assigning a period. The unknown group is a finding about the record quality.","Include transcripts, summaries, and downloaded audio. These copies may not look like recordings, but they contain the same information. Add them to the same inventory and apply the same rule. A summary in a shared document is still a record of the call.","Record the access group for each storage location. A recording may be scheduled for deletion but still visible to a wide group. The access list is part of the inventory because a copy that many people can download is harder to control. Review the group when the retention period changes."]},{"id":"define-retention","heading":"Define the retention rule","paragraphs":["Write the retention period for each purpose rather than one period for all calls. A quality sample may need a short window, while a dispute may need a longer one. Check the client contract and the applicable law before setting the period. The stricter requirement wins when they conflict.","Record the start date for the period. It may be the call date, the end of the client relationship, or the resolution of a dispute. A rule that does not say when the clock starts cannot be enforced. The start date is part of the retention definition.","Define what counts as deletion. Removing a file from a folder may leave a copy in a recycle bin, a backup, or a sync service. A complete deletion removes the content from the active system and follows the backup schedule. The rule should say which standard the team is using."]},{"id":"measure-the-overrun","heading":"Measure the overrun","paragraphs":["For each recording past its deletion date, record how long it has overrun and where it is stored. Add the reason it remains, such as a hold, a missed cleanup, or an unknown owner. The reason is more useful than the count alone. A single systemic cause may explain most of the overrun.","Report the share of recordings past the rule, the median overrun, and the oldest item. A small tail of very old recordings may be more dangerous than a broad short delay. The oldest item often shows where the deletion process has stopped entirely. A single cause may explain most of the tail, so read the reasons before acting.","Compare the inventory with the policy. A policy that covers audio but not transcripts has a gap. A policy that covers the main system but not exports has another. The comparison shows whether the rule matches the actual storage."]},{"id":"why-deletion-fails","heading":"Why deletion fails","paragraphs":["Deletion fails when it depends on a person remembering. The task is easy to postpone because no client is asking for it. The fix is an automated rule in the system, with a periodic check that the rule is still active. A manual cleanup should be the exception, not the main control.","Deletion also fails when a hold is applied and never removed. A legal or client hold may be valid, but it needs an owner and a review date. An indefinite hold without a reason is a storage decision disguised as a legal one. The inventory should show the hold and the reviewer.","A third cause is an export that creates a copy outside the controlled system. The export may be made for a client request or a quality review and then forgotten. The fix is to record the export, set a deletion date, and check it. The copy is part of the retention problem.","A fourth cause is a backup that follows a different schedule. The active system may delete the recording while the backup keeps it for months. The retention rule should state how backups are handled and who verifies the cycle. A deletion that ignores backups is incomplete."]},{"id":"controls-that-help","heading":"Controls that help","paragraphs":["Set the retention rule in the system and test it on a sample. A rule that has never been tested may not cover the copies or the backups. Record the test date and the result. The test should confirm that the content is gone, not only that a setting is enabled.","Keep a deletion receipt with the identifier, the date, and the method. Do not keep the content just to prove it was deleted. The receipt is enough for most reviews and is safer than an archive. Store it with the retention log.","Review the vendors and the export paths each year. A vendor default may be longer than the client expects, and an export may create a copy no one tracks. Get the vendor answer in writing and add it to the inventory. The client agreement should match the vendor setting.","Make the deletion receipt easy to find. A reviewer should be able to match a recording identifier to a date and a method without opening the old content. Store the receipt in the same system as the retention log. The record proves the control worked without preserving the sensitive material."]},{"id":"method-and-limitations","heading":"Method and limitations","paragraphs":["This review describes a local inventory method rather than a study of retention practices across providers. The sample depends on the systems the team can access and the records that exist. A hidden copy or a backup may not appear in the inventory. The result is a floor rather than a complete count.","The legal and client requirements may change during the review. A new agreement or a new rule can make an old period wrong. The review should record the version of the policy it used. A later review should repeat the comparison with the current rule.","The inventory should note which systems were not accessible during the review. A missing system is a gap in the result, not proof that no recordings exist there. List the excluded systems and the reason. A later review can close the gap when access is available."]},{"id":"decision-checklist","heading":"Decision checklist","paragraphs":["Inventory every system and copy that can hold a recording. Add the purpose, the owner, the start date, and the expected deletion date. Define the retention period by purpose and the meaning of deletion. Record the owner and the method for each copy so the receipt can be checked.","Measure the share past the rule, the median overrun, and the oldest item. Find the holds, the manual gaps, and the exports. Automate the rule and test it. Keep a deletion receipt and review vendors each year."]}]},{"publicationStatus":"reviewed","kind":"research","slug":"how-complete-are-supplier-contacts-before-an-assistant-uses-them","title":"How complete are supplier contacts before an assistant uses them?","description":"A method for checking whether a supplier record has the role, channel, authority, and verification date needed for safe action.","published":"2026-11-11","readingMinutes":8,"heroImage":"/hero/november-11/how-complete-are-supplier-contacts-before-an-assistant-uses-them-hero.webp","thumbnail":"/thumbnails/november-11/how-complete-are-supplier-contacts-before-an-assistant-uses-them.webp","heroAlt":"How complete are supplier contacts before an assistant uses them?","topic":"supplier contacts","relatedService":{"href":"/services","label":"Explore staffing services"},"relatedResource":{"href":"/blog/build-a-supplier-contact-verification-sheet","label":"Read the supplier contact verification guide"},"sources":[{"label":"U.S. Small Business Administration hire and manage employees","href":"https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"},{"label":"NIST Baldrige Excellence Framework","href":"https://www.nist.gov/baldrige"},{"label":"CISA Cyber Essentials","href":"https://www.cisa.gov/cyber-essentials"}],"sections":[{"id":"question-and-scope","heading":"Question and scope","paragraphs":["This review asks how complete a supplier contact record is before an assistant uses it to act. The unit is one supplier contact used for a routine or urgent request. The scope covers suppliers that support client work, payments, deliveries, or software. The review does not estimate a universal completeness rate, because the supplier mix and the risk level vary.","The question matters because an incomplete contact record can cause a delayed delivery, a missed payment, or a fraudulent change. The assistant may have a name but not a role, a channel, or a limit. The record looks usable until the moment it is tested. A short verification before use is cheaper than a correction after the fact.","The review separates a missing field from an unverified field. A record may have a phone number that was never checked, or a role that was copied from an old email. The field exists, but it may not be current. Completeness includes verification, not only presence.","The review also asks whether the assistant knows the limit of the contact. A record may name a person but not say whether that person can approve a payment change or only a delivery date. The limit is part of completeness because it tells the assistant when to pause. An unclear limit turns a routine request into a guessing game."]},{"id":"build-the-sample","heading":"Build the sample","paragraphs":["Take the suppliers the assistant contacted in the past month. Include routine orders, invoice questions, delivery changes, and urgent issues. Add the suppliers that appear in the client contract even if they were not contacted. The sample should cover the relationships that matter, not every company in the directory.","For each supplier, record the contact name, role, company, channel, hours, backup, and the last verification date. Add the account reference and the risk level. If a field is missing, record it as missing rather than leaving it blank. The blank may hide a gap that the team has learned to work around.","Compare the record with the source that created it. The source may be a contract, a supplier email, or a client introduction. If the record cannot be traced to a source, mark it as unverified. A name without a source is a guess that may have been repeated for years.","Record the last time the contact was used and whether the request succeeded. A contact that has not been used in a year is more likely to be stale. A contact that failed recently is a priority for repair. The usage history helps rank the findings."]},{"id":"define-complete","heading":"Define complete","paragraphs":["A complete contact has a named person, a role, a verified channel, and a reason to contact them. It also has a backup and an escalation path for urgent work. The record should show the last verification date and the source. Without those, the team cannot tell whether the contact is current.","The required fields should match the risk. A low-risk stationery supplier may need only a general support line, while a payment processor needs a named account manager and a verified escalation path. Do not apply the same template to every supplier. The risk level should decide the depth.","A complete record also states what the assistant may do without approval. A delivery reschedule may be within scope, while a bank detail change is not. The limit belongs beside the contact. The assistant should know when to pause and ask the account owner."]},{"id":"measure-completeness","heading":"Measure completeness","paragraphs":["Report the share of contacts with every required field and the share missing at least one. Add the share with no verification date and the share with a channel that was never tested. The four numbers show whether the record is present, current, and usable. Read them together rather than reducing the result to a single score.","Group the results by supplier risk and by client. A high-risk supplier with a missing escalation path is a bigger finding than a low-risk supplier with no backup. A client with many unverified contacts may need a different onboarding step. The grouping helps prioritize the repair.","Compare the record with the outcome of the last request. A contact that worked may still be incomplete for an urgent case. A contact that failed may be complete on paper but wrong in practice. The comparison shows whether the fields predict a usable path."]},{"id":"why-records-decay","heading":"Why records decay","paragraphs":["A supplier record decays when a person changes role and no one updates the sheet. The old name may still receive email for a while, which hides the change. The next urgent request reaches the wrong person. The fix is a verification step at each supplier contact, not only a yearly review.","A record also decays when the channel changes. A supplier may move from phone to a portal, or from a personal email to a support queue. The old channel may still appear to work for routine messages. The urgent case reveals that no one is monitoring it. Test the channel before relying on it.","A third cause is a record created from an invoice or a marketing message. Those sources may contain a sales contact rather than the account manager. The record looks complete but points to the wrong role. The fix is to verify against the contract or the client introduction.","A fourth cause is a supplier that changes its own support model. A named account manager may be replaced by a shared queue or a portal. The old record may still work for a while, which hides the change. Ask the supplier to confirm the current path at each contract review."]},{"id":"controls-that-help","heading":"Controls that help","paragraphs":["Require a source and a verification date for each contact. Make the source a link or a document reference, not a name alone. Review the unverified contacts first and either confirm or remove them. A short verified list is more useful than a long unverified one.","Test the channel before an urgent request. Send a routine message and confirm a reply, or call the number on the contract. Record the result. A channel that has not been tested is a hope, not a path. The test is especially important for payment and delivery contacts.","Review the sheet when a supplier or client changes. Add the review to the quarterly client check-in and the supplier onboarding. Record the change and the person who verified it. The sheet should describe the current relationship, not the one from last year.","Keep a short risk tier beside each supplier. The tier decides how often the contact is verified and how much detail is required. A payment supplier may need a quarterly check, while a stationery supplier may need a yearly one. The tier keeps the review proportional to the risk."]},{"id":"method-and-limitations","heading":"Method and limitations","paragraphs":["This review describes a local completeness check rather than a study of supplier records across providers. The sample depends on the contacts the team uses and the records available. Some suppliers may be reached through a client contact who is not in the sheet. The result is a floor rather than a full census.","The review may also change behavior. The team may verify contacts more carefully because the sample is being checked. That effect is useful, but it makes the first period a weak baseline. Use a later period and note when the review began.","The sample should also include a supplier that was never contacted. A record can look complete because no one has tested it. Including an unused supplier shows whether the sheet is maintained for the whole relationship or only for the busy accounts. The comparison is useful even when the sample is small."]},{"id":"decision-checklist","heading":"Decision checklist","paragraphs":["List the suppliers used in the past month and the fields needed for each risk level. Add the source, verification date, backup, and assistant limit. Mark missing and unverified fields separately. Use the same fields for every supplier at the same risk level.","Report the complete, incomplete, unverified, and untested shares. Group by supplier risk and client. Require a source for new contacts. Test the channel and review the sheet after every change."]}]}];
